import{m as a,g as t,i as s,y as i}from"./chunks/framework.CyQWWwrP.js";const g=JSON.parse('{"title":"Starter Templates","description":"","frontmatter":{},"headers":[],"relativePath":"guidance/starter-templates.md","filePath":"guidance/starter-templates.md"}'),n={name:"guidance/starter-templates.md"};function o(l,e,r,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="starter-templates" tabindex="-1">Starter Templates <a class="header-anchor" href="#starter-templates" aria-label="Permalink to &quot;Starter Templates&quot;">​</a></h1><p>Use the Cobalt CLI when you are creating a new application and want Cobalt dependencies, global styles, and a working framework shell created for you.</p><p>Install and configure the CLI first using the <a href="/cobalt-design-system/resources/cli.html">Cobalt CLI documentation</a>, then run the starter flow:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-dark-high-contrast github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#FFB757;--shiki-light:#6F42C1;">co</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> new</span></span></code></pre></div><p>The generator prompts for a framework template, whether to use SCSS, whether to include the Cobalt app shell pattern, and where Cobalt packages should be installed from.</p><h2 id="skip-prompts" tabindex="-1">Skip Prompts <a class="header-anchor" href="#skip-prompts" aria-label="Permalink to &quot;Skip Prompts&quot;">​</a></h2><p>Pass flags when you already know the project shape:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-dark-high-contrast github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#FFB757;--shiki-light:#6F42C1;">co</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> new</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> my-app</span><span style="--shiki-dark:#91CBFF;--shiki-light:#005CC5;"> --template</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> react</span><span style="--shiki-dark:#91CBFF;--shiki-light:#005CC5;"> --scss</span><span style="--shiki-dark:#91CBFF;--shiki-light:#005CC5;"> --app-shell</span></span></code></pre></div><p>When saved CLI registry settings exist, the generator writes a project <code>.npmrc</code> and removes <code>.npmrc.example</code>. If you pass <code>--no-configure-registry</code>, the generated project keeps <code>.npmrc.example</code> with the private registry settings you need to copy into your project before installing dependencies.</p><h2 id="use-local-package-mode" tabindex="-1">Use Local Package Mode <a class="header-anchor" href="#use-local-package-mode" aria-label="Permalink to &quot;Use Local Package Mode&quot;">​</a></h2><p>For local testing with unpublished tarballs or with the downloaded <a href="/cobalt-design-system/resources/artifacts.html#cobalt-packages">Cobalt Package Bundle</a>, choose local package mode:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-dark-high-contrast github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#FFB757;--shiki-light:#6F42C1;">co</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> new</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> my-app</span><span style="--shiki-dark:#91CBFF;--shiki-light:#005CC5;"> --cobalt-source</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> local</span></span></code></pre></div><p>Local package mode points Cobalt dependencies at <code>./cobalt-packages/*.tgz</code> and writes copy instructions in <code>cobalt-packages/README.md</code>. If you are using the bundle artifact, extract it and copy the <code>cobalt-packages</code> folder into the generated project before installing dependencies.</p><h2 id="what-the-templates-include" tabindex="-1">What the Templates Include <a class="header-anchor" href="#what-the-templates-include" aria-label="Permalink to &quot;What the Templates Include&quot;">​</a></h2><p>Templates include the package dependencies, Cobalt token stylesheet import, starter page structure, and framework-specific event wiring needed to render and test a Cobalt component. App shell templates also include the Cobalt shell pattern with navigation rail, navigation drawer, header, banner, and mode toggle.</p><p>Use the guidance in <a href="/cobalt-design-system/getting-started/developers.html">Getting Started for Developers</a> when you need to add Cobalt to an existing project instead of creating a new starter.</p>',16)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
